parameters.jsCode:
﻿// El locator autoritativo viene de la API, nunca del modelo. El documento tampoco:
// file_name y file_url viajan por el registro junto al locator, para que la cita llegue
// completa aunque el agente no los copie.
//
// Las citas atravesaron dos agentes LLM. Si alguno altero un citation_id, aca no se
// encuentra y la cita sale sin ubicacion. Es el modo de fallo buscado: una cita sin
// ubicacion es aceptable, una con la ubicacion equivocada no lo es.
//
// original_snippet es lo unico que el modelo aporta a la ubicacion, y solo como puntero:
// la API lo verifica contra el fragmento que realmente recupero antes de reanclar la cita.

// El corpus es markdown convertido desde PDF, asi que el pasaje literal llega con titulos
// (#), negritas (**), cursivas (_), reglas (-----), filas de tabla (|), comentarios
// (<!-- image -->) y entidades HTML. Eso sirve para anclar la cita, no para leerla. Se
// limpia aca, despues de /resolve-locators, porque la API compara el texto tal como vino
// contra el fragmento recuperado: limpiarlo antes romperia el anclaje.
//
// El agente devuelve el pasaje aplanado en una sola linea y con las comillas escapadas
// (\"), asi que ningun marcador se puede buscar solo a principio de linea: un titulo o una
// regla horizontal aparecen a media frase. Cada marcador se trata en las dos posiciones.
const HTML_ENTITIES = {
  '&lt;': '<',
  '&gt;': '>',
  '&amp;': '&',
  '&quot;': '"',
  '&apos;': "'",
  '&#39;': "'",
  '&nbsp;': ' ',
};

// Las tablas del corpus repiten la misma celda en todas las columnas. Se colapsa la celda
// consecutiva repetida para no leer cinco veces el mismo titulo.
function flattenTableRow(line) {
  const cells = line.split('|').map((cell) => cell.trim()).filter(Boolean);
  return cells.filter((cell, index) => cell !== cells[index - 1]).join(' ');
}

// La marca de fe de erratas "(*)" es texto de la norma, no enfasis. Se aparta antes de
// tocar los asteriscos y vuelve al final.
const ERRATA_MARK = '\u0000errata\u0000';

function toPlainText(value) {
  if (typeof value !== 'string') return '';

  const unescaped = value
    // El pasaje viaja escapado: \n y \" son dos caracteres, no un salto ni una comilla.
    .replace(/\\[nrt]/g, ' ')
    .replace(/\\(["'\\])/g, '$1')
    .replace(/\\([^\w\s])/g, '$1')
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/&(?:lt|gt|amp|quot|apos|nbsp|#39);/g, (entity) => HTML_ENTITIES[entity] || ' ')
    .replace(/<\/?[a-zA-Z][^>]*>/g, ' ')
    .split(/\(\s*\*\s*\)/).join(ERRATA_MARK);

  const lines = unescaped
    .split(/\r?\n/)
    .map((line) => {
      // Separador de tabla y regla horizontal: no aportan texto.
      if (/^\s*\|?\s*:?-{2,}/.test(line)) return '';
      if (/^\s*([-*_])\s*(\1\s*){2,}$/.test(line)) return '';

      let text = line.includes('|') ? flattenTableRow(line) : line;
      text = text.replace(/^\s{0,3}#{1,6}\s*/, '');
      text = text.replace(/^\s*>+\s?/, '');
      // Solo se quita la vinieta. La numeracion se conserva: en una norma "2." es el inciso.
      text = text.replace(/^\s*[-*+]\s+/, '');
      return text;
    })
    .filter((line) => line.trim());

  return lines
    .join(' ')
    .replace(/!\[([^\]]*)\]\([^)]*\)/g, '$1')
    .replace(/\[([^\]]+)\]\([^)]*\)/g, '$1')
    // Regla horizontal y titulo a media frase: quedan asi cuando el pasaje llega aplanado.
    .replace(/(^|\s)[-–—*_]{3,}(?=\s|$)/g, '$1')
    .replace(/(^|[\s"”'’)\].,;:!?])#{1,6}\s+/g, '$1')
    .replace(/\s*\|\s*/g, ' ')
    .replace(/\*\*([\s\S]+?)\*\*/g, '$1')
    .replace(/__([\s\S]+?)__/g, '$1')
    .replace(/\*([\s\S]+?)\*/g, '$1')
    .replace(/_([\s\S]+?)_/g, '$1')
    // El OCR deja pares de enfasis sin cerrar, sobre todo cuando el pasaje corta a mitad de
    // una cursiva. Los sueltos se quitan: el guion bajo solo sobrevive dentro de una palabra.
    .replace(/\*+/g, '')
    .replace(/(^|[^0-9a-zA-ZáéíóúüñÁÉÍÓÚÜÑ])_+|_+(?![0-9a-zA-ZáéíóúüñÁÉÍÓÚÜÑ])/g, '$1')
    .replace(/`+/g, '')
    .split(ERRATA_MARK).join('(*)')
    // El PDF deja el texto con espacios repartidos dentro de las palabras y cortes de linea
    // a mitad de frase: ambos colapsan a un espacio simple.
    .replace(/\s+/g, ' ')
    .replace(/\s+([,.;:!?%)\]])/g, '$1')
    .replace(/([(\[])\s+/g, '$1')
    .trim();
}

const xai = $('XAI Agent').first().json;
const payload = xai.output || xai;
const citations = Array.isArray(payload.citations) ? payload.citations : [];

let authoritative = new Map();
try {
  const resolved = $json.citations || [];
  for (const entry of resolved) {
    if (entry && entry.citation_id) authoritative.set(entry.citation_id, entry);
  }
} catch (error) {
  // Si /resolve-locators fallo, ninguna cita lleva ubicacion. El chat sigue.
  authoritative = new Map();
}

// La cita se rearma campo por campo en vez de extender la del modelo: asi no viaja al
// backend nada que el agente haya agregado por su cuenta.
const enriched = citations.map((citation) => {
  const match = authoritative.get(citation.citation_id) || {};
  return {
    citation_id: citation.citation_id || '',
    // El resumen que lee el usuario: el unico texto de la cita que redacta el agente.
    summary_snippet: toPlainText(citation.summary_snippet),
    // El pasaje literal ya cumplio su papel de puntero; al usuario le llega legible.
    original_snippet: toPlainText(citation.original_snippet),
    file_name: match.file_name || '',
    file_url: match.file_url || '',
    locator: match.locator || '',
    breadcrumb: match.breadcrumb || '',
    locator_source: match.locator_source || '',
    // excerpt = ubicado por el pasaje citado; excerpt_multi = el pasaje cruza articulos y
    // se citan todos; chunk = ubicado por el fragmento completo; ambiguous = abarcaba
    // varios articulos y no se pudo verificar cual.
    locator_scope: match.locator_scope || '',
  };
});

// Dos citation_id distintos pueden terminar en el mismo pasaje del mismo articulo: el
// agente cito dos veces lo mismo y le puso otro resumen a cada copia. En pantalla eso sale
// como el articulo repetido. Se conserva la primera cita, con la version mas completa del
// pasaje; el segundo resumen se descarta porque dice lo mismo con otras palabras.
function passageKeyText(value) {
  return String(value || '').toLowerCase().replace(/[^0-9a-záéíóúüñ]+/g, '');
}

function sameDocument(a, b) {
  return (a.file_url || a.file_name) === (b.file_url || b.file_name);
}

// El recorte del pasaje lo elige el modelo, asi que dos copias del mismo tramo pueden
// diferir en donde empiezan o terminan: se comparan por contencion, no por igualdad.
function samePassage(a, b) {
  if (!sameDocument(a, b) || a.locator !== b.locator) return false;

  const left = passageKeyText(a.original_snippet);
  const right = passageKeyText(b.original_snippet);
  if (!left || !right) return left === right;
  return left.includes(right) || right.includes(left);
}

const deduped = [];
for (const citation of enriched) {
  const twin = deduped.find((existing) => samePassage(existing, citation));
  if (!twin) {
    deduped.push(citation);
    continue;
  }
  if (citation.original_snippet.length > twin.original_snippet.length) {
    twin.original_snippet = citation.original_snippet;
  }
}

return [{ json: { ...payload, citations: deduped } }];

// Aca se decide si la conversacion necesita una vuelta de preguntas antes de buscar en el
// corpus. Es una decision de flujo, no de redaccion: el Parser Agent dice que le falta,
// pero quien corta el paso a la busqueda es este nodo, con reglas verificables.
//
// El texto que lee el usuario se arma aca y no en el agente. El modelo solo aporta las
// preguntas; el encabezado, el orden y la salida honrosa ("puedo orientarte igual") son
// fijos. Asi el mensaje de preguntas siempre se reconoce despues por su encabezado, que es
// justamente lo que impide preguntar dos veces seguidas.
const CLARIFICATION_HEADING = 'Para orientarte mejor';
// El XAI Agent tambien puede cerrar su respuesta con preguntas, bajo su propio encabezado.
// Cuentan igual: si el ultimo turno del asistente ya pregunto, este no vuelve a preguntar.
const XAI_FOLLOW_UP_HEADING = 'Para afinar la orientacion';
const MAX_QUESTIONS = 3;

const output = $json.output || {};
// El nodo Agent no propaga el item de entrada, asi que el historial se lee del Webhook.
const body = $('Webhook').first().json.body || {};
const previousMessages = Array.isArray(body.previous_messages) ? body.previous_messages : [];

const questions = (Array.isArray(output.clarifying_questions) ? output.clarifying_questions : [])
  .map((question) => String(question || '').trim())
  .filter(Boolean)
  .slice(0, MAX_QUESTIONS);

const ALLOWED_SUFFICIENCY = ['SUFFICIENT', 'PARTIAL', 'INSUFFICIENT'];
const declared = String(output.information_sufficiency || '').trim().toUpperCase();
// Sin senal utilizable el flujo queda como estaba: se busca y se responde.
const sufficiency = ALLOWED_SUFFICIENCY.includes(declared) ? declared : 'SUFFICIENT';

// Solo importa el ultimo turno del asistente. Si ese turno ya fue una tanda de preguntas,
// el mensaje actual es la respuesta del usuario y toca orientar, aunque siga faltando algo:
// preguntar de nuevo sobre la respuesta recien dada es el bucle que hay que evitar. Turnos
// mas antiguos no bloquean, porque un tema nuevo mas adelante puede merecer sus preguntas.
const lastAssistantMessage = [...previousMessages]
  .reverse()
  .find((message) => String(message.role || '').trim().toUpperCase() === 'ASSISTANT');
const lastAssistantContent = String((lastAssistantMessage || {}).content || '');
const askedInPreviousTurn = lastAssistantContent.includes(CLARIFICATION_HEADING)
  || lastAssistantContent.includes(XAI_FOLLOW_UP_HEADING);

const shouldAsk = sufficiency === 'INSUFFICIENT' && questions.length > 0 && !askedInPreviousTurn;

// Cuando se pregunta, el turno se agota aca: no hay busqueda ni cita que mostrar, y por eso
// cuesta un token en vez de tres. La salida tiene que dejar seguir al usuario que no sabe o
// no quiere responder, o las preguntas se vuelven un requisito para ser atendido.
const message = [
  `**${CLARIFICATION_HEADING}**`,
  '',
  'Puedo ayudarte con esto, pero un par de datos generales cambian bastante la orientacion:',
  '',
  ...questions.map((question) => `- ${question}`),
  '',
  'Responde solo lo que sepas y sin datos personales sensibles. Si prefieres, dime "sigue igual" y te doy una orientacion general con lo que ya me contaste.',
].join('\n');

return [{
  json: {
    ...$json,
    clarification: {
      status: sufficiency,
      questions,
      shouldAsk,
      askedInPreviousTurn,
      // Las preguntas que no cortan el flujo siguen viajando: el RAG y el XAI las usan para
      // no dar por cierto lo que el usuario nunca dijo.
      message: shouldAsk ? message : '',
    },
  },
}];

// El idioma decide unicamente en que lengua se lee la orientacion. El razonamiento
// juridico, el corpus y las citas siguen siendo en espanol de punta a punta.
const SUPPORTED = ['es', 'qu', 'ay'];
const body = $json.body || {};
const requested = String(body.language || '').trim().toLowerCase();
// Un idioma ausente o desconocido cae a espanol en lugar de fallar: el backend ya valida
// la lista blanca, y aca un valor raro no debe costarle el turno al usuario.
const language = SUPPORTED.includes(requested) ? requested : 'es';
return [{ json: { ...$json, body: { ...body, language } } }];

