parameters.jsCode:
// La traduccion viaja JUNTO al espanol, nunca en su lugar. El backend guarda el espanol
// como version canonica y el frontend ofrece verlo, asi que perder el original seria
// perder la unica version verificable contra las normas citadas.
//
// El aviso de traduccion automatica no se agrega aca a proposito: lo muestra el frontend
// junto al conmutador 'Ver en espanol'. Incrustarlo en el texto lo dejaria congelado en la
// base de datos y duplicado en pantalla.
const base = $('If Needs Localization').first().json;
const payload = base.payload || {};
const translation = $json.output || {};
const asArray = (value) => (Array.isArray(value) ? value.map((item) => String(item || '')) : []);

// Sin traduccion utilizable se entrega el espanol tal cual. Es peor experiencia, pero es
// contenido correcto; devolver el turno vacio o cobrarlo dos veces seria peor.
const messageLocalized = String(translation.message || '').trim() || null;

const citations = (payload.citations || []).map((citation, index) => ({
  ...citation,
  // Solo se traduce el resumen. `original_snippet` es el texto literal de la norma y se
  // queda en espanol: es lo unico que permite contrastar la cita contra la fuente.
  summary_snippet_localized: asArray(translation.citationSummaries)[index] || null,
}));

return [{
  json: {
    ...payload,
    // El idioma en que se responde de verdad, y el que habia pedido la interfaz. Cuando
    // difieren, el backend los persiste y el frontend explica el cambio.
    language: base.language || 'es',
    language_requested: base.languageRequested || base.language || 'es',
    citations,
    message_localized: messageLocalized,
    nextSteps_localized: asArray(translation.nextSteps),
    clarifyingQuestions_localized: asArray(translation.clarifyingQuestions),
    // El espanol del mensaje del usuario ya lo produjo Translate Inbound. El backend lo
    // necesita para dejar el historial en un solo idioma.
    user_message_es: $('Normalized Input').first().json.body.message,
  },
}];

// La rama espanola no traduce nada, pero tiene que entregar el mismo contrato que la otra.
// Por aca pasan dos casos: la conversacion que ya era en espanol, y la que pedia quechua o
// aymara pero se escribio en espanol. En el segundo `language_requested` difiere, y es lo
// unico que permite avisarle al usuario de que se le respondio en otra lengua.
return [{
  json: {
    ...($json.payload || {}),
    language: $json.language || 'es',
    language_requested: $json.languageRequested || $json.language || 'es',
  },
}];
